  LinearLayout actions=new LinearLayout(c);Button add=button("Adicionar jogo");AppStyle.button(add,true);actions.addView(add,new LinearLayout.LayoutParams(0,-2,1));add.setOnClickListener(v->catalog());
  Button options=button("Opções");LinearLayout.LayoutParams op=new LinearLayout.LayoutParams(-2,-2);op.setMargins(dp(8),0,0,0);actions.addView(options,op);options.setOnClickListener(v->options());body.addView(actions);
  search=NativeSheet.input(c,"Buscar no Meu Retrô",160);search.setSingleLine(true);ActionIcon icon=new ActionIcon(ActionIcon.SEARCH,0xffb2a9c1);icon.setBounds(0,0,dp(20),dp(20));search.setCompoundDrawables(icon,null,null,null);search.setCompoundDrawablePadding(dp(10));body.addView(search);
